+    assert.equal(verifyVerdictFor("REVIEW_REJECTED"), "BLOCKED");
+    assert.equal(verifyExitNameFor("REVIEW_REJECTED"), "blocked");
+    assert.equal(verifyExitCode("blocked"), 3);
+  });
+});
