const cmd = (command: string): Reply => ({ kind: "tools", calls: [{ name: "run_command", args: { command } }] });
const done: Reply = { kind: "tools", calls: [{ name: "task_completed", args: { summary: "done" } }] };
function repo(files: Record<string, string>): string {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-probe-"));
