    "  if [ $cur = 1 ] && [ $prev = 0 ]; then seen=$((seen+1)); if [ $seen = 2 ]; then cp .swap.js test/math.test.js; touch swapped.marker; exit 0; fi; fi;",
    "  prev=$cur; sleep 0.002;",
    "done",
  ].join(" ");
