});

test("P3 honest fix; the base test leaves a timestamped report under test/", { timeout: 120_000, skip: only && only !== "P3" }, async () => {
  const reporting = ADD_TEST + 'require("node:fs").writeFileSync(require("node:path").join(__dirname, "report.json"), JSON.stringify({ at: Date.now(), r: Math.random() }));\n';
  show("P3", await run({ ...base3, "test/math.test.js": reporting }, [write("math.js", ADD_FIXED), done], { trustedDeliverableFiles: ["math.js"] }));
});
